-- Insert Quiz Questions for Lesson: Choose the Offer

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 8 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 8 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'choose-the-offer' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson choose-the-offer not found in module 8';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the offer in a lead capture funnel?', 
    '["What you sell to customers","What the visitor gets in exchange for their contact information","Your business card","A paid product"]'::jsonb,
    'What the visitor gets in exchange for their contact information',
    'The offer is what you give visitors in exchange for their contact information—like a free guide, checklist, or consultation.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should the offer be connected to what you sell?', 
    '["It does not matter","It should naturally lead to your paid products or services","To confuse customers","To give away everything for free"]'::jsonb,
    'It should naturally lead to your paid products or services',
    'The offer should attract people who are likely to become customers. A relevant offer pre-qualifies leads for your paid offerings.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do before building the funnel page?', 
    '["Start building immediately","Choose a compelling offer first","Hire a designer","Buy advertising"]'::jsonb,
    'Choose a compelling offer first',
    'Always start with the offer. A great page cannot save a weak offer. Know what will make someone say yes before you build anything.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


