-- Insert Quiz Questions for Lesson: Build the Funnel Page

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 8 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 8 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'build-funnel-page' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson build-funnel-page not found in module 8';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the main job of a funnel page?', 
    '["Explain everything about your business","Get the visitor to fill out the form","Show your entire product catalog","Link to your social media"]'::jsonb,
    'Get the visitor to fill out the form',
    'A funnel page has one job: convert visitors into leads by getting them to fill out the form. Everything on the page should support that goal.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How many bullet points should you use?', 
    '["As many as possible","3 to 5 simple bullet points","None","Exactly 10"]'::jsonb,
    '3 to 5 simple bullet points',
    'Use 3 to 5 bullet points to highlight key benefits. Too many bullet points overwhelm visitors; too few may not provide enough motivation.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you remove from a funnel page?', 
    '["The headline","Navigation menus and distractions that take people away from the form","The form","The button"]'::jsonb,
    'Navigation menus and distractions that take people away from the form',
    'Remove navigation menus, multiple offers, and external links that could distract visitors from completing the form. Keep the page focused on one goal.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


