-- Insert Quiz Questions for Lesson: Create the Lead Capture Form

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 8 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 8 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'create-lead-capture-form' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson create-lead-capture-form not found in module 8';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What fields should you start with for most funnels?', 
    '["Full address, company size, budget, website","First Name and Email","Social security number and birth date","Credit card information"]'::jsonb,
    'First Name and Email',
    'Start with First Name and Email. These give you what you need to follow up while keeping friction low. Add more fields only if truly necessary.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you minimize form fields?', 
    '["To make the form look prettier","More fields create more friction and reduce completion rates","Fields cost extra money","LeadProspectrr limits fields"]'::jsonb,
    'More fields create more friction and reduce completion rates',
    'Every additional field creates friction. Visitors are more likely to complete short forms. Only ask for information you truly need.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where should the form redirect after submission?', 
    '["Back to the homepage","To the thank-you page","To a competitor''s website","Nowhere, leave them on the same page"]'::jsonb,
    'To the thank-you page',
    'Always redirect to a thank-you page after form submission. This confirms the action, sets expectations, and guides them to the next step.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


