-- Insert Quiz Questions for Lesson: Build the Follow-Up Workflow

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 8 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 8 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'build-follow-up-workflow' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson build-follow-up-workflow not found in module 8';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should be the first step in a follow-up workflow?', 
    '["Send a sales pitch immediately","Add a tag to identify where the lead came from","Delete the lead","Wait one week"]'::jsonb,
    'Add a tag to identify where the lead came from',
    'The first step should be adding a tag. This helps you identify the lead source and segment your contacts for appropriate follow-up.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why send an internal notification?', 
    '["To spam your team","So the business owner or team knows a new lead came in","It is required by law","To charge the lead money"]'::jsonb,
    'So the business owner or team knows a new lead came in',
